// === Tab: mySketch ===
let objs = [];
let objsNum = 50;

const palette = ["#FF00D8", "#FFB201", "#98FF00", "#00FFC4", "#0082FE", "#B733FF"];

function setup() {
    // Calculate a canvas size that fits the screen while maintaining a 1080:1920 ratio
  let canvasHeight = window.innerHeight * 0.8;
  let canvasWidth = (1080 / 1920) * canvasHeight;

  createCanvas(canvasWidth, canvasHeight);

  angleMode(DEGREES);
  noFill();

  background(20);

  for (let i = 0; i < objsNum; i++) {
    objs.push(new Obj(i));
  }
}

function draw() {
  blendMode(BLEND);
  background(20, 50);

  blendMode(ADD);

  for (let i = 0; i < objs.length; i++) {
    objs[i].move();
    objs[i].display();
  }
}

class Obj {
  constructor(tmpIndex) {
    this.index = tmpIndex;
    // We now have both a startX and startY.
    this.startX = random(width);
    this.startY = random(height);
    this.init();
    // The range is now applied to both axes.
    this.goalX = this.startX + this.rangeX;
    this.goalY = this.startY + this.rangeY;
  }

  init() {
    // The range and step values will apply to both x and y.
    this.range = random(10, 200);
    this.step = random(5, 8);
    this.strWeight = random(15, 25);
    this.c = color(random(palette));
    this.c.setAlpha(50);
  }

  move() {
    // We move both the X and Y positions by the same step value.
    this.startX += this.step;
    this.startY += this.step;
    this.goalX = this.startX + this.range;
    this.goalY = this.startY + this.range;

    // We check if the line has moved off the bottom or right side of the canvas.
    if (this.startX > width || this.startY > height) {
      this.init();
      // We reset both X and Y to just off the top-left corner.
      this.startX = -this.range;
      this.startY = -this.range;
      this.goalX = this.startX + this.range;
      this.goalY = this.startY + this.range;
    }
  }

  display() {
    strokeWeight(this.strWeight);
    stroke(this.c);
    beginShape();
    // The loop now iterates diagonally, but we'll stick to one axis for simplicity.
    // Let's loop through the X values. The Y values will be calculated relative to X.
    for (let x = this.startX; x <= this.goalX; x++) {
      // We calculate a y value that creates a diagonal "path".
      // We use the startY and the difference from the startX to create the diagonal.
      // Perlin noise is still applied to create the wavy effect.
      // We use the mapped Y value to adjust the vertex's Y position.
      let noiseY = map(noise(x * 0.001, this.index * 0.1, frameCount * 0.002), 0, 1, -height * 0.25, height * 1.25);
      let y = (x - this.startX) + this.startY + noiseY;

      vertex(x, y);
    }
    endShape();
  }
}

